<?php require dirname(__DIR__).'/app/bootstrap.php';$me=require_login();$module=(string)($_GET['module']??'overview');$error='';
function module_redirect(string $module):never{header('Location: '.path('admin/modules.php?module='.rawurlencode($module)));exit;}
function module_require_any(array $permissions):void{foreach($permissions as $permission)if(can($permission))return;http_response_code(403);exit('Permission denied.');}
if($module==='advertising'){module_require_any(['advertising.manage','advertising.approve']);header('Location: '.path('admin/advertising.php'));exit;}
function module_currency(string $value):string{$currency=strtoupper(trim($value));if(!preg_match('/^[A-Z]{3}$/',$currency))throw new RuntimeException('A valid three-letter currency is required.');return $currency;}
function module_date(string $value,string $label,bool $future=false):string{$time=strtotime(trim($value));if($time===false||($future&&$time<=time()))throw new RuntimeException($label.' must be a valid'.($future?' future':'').' date and time.');return date('Y-m-d H:i:s',$time);}
function module_money(int $minor,string $currency):string{$zero=in_array(strtoupper($currency),['RWF','JPY'],true);return strtoupper($currency).' '.number_format($zero?$minor:$minor/100,$zero?0:2);}
if($_SERVER['REQUEST_METHOD']==='POST'){
 csrf_verify();try{$act=(string)($_POST['action']??'');
  if($act==='create_advertiser'){require_permission('advertising.manage');$name=trim((string)($_POST['name']??''));$email=strtolower(trim((string)($_POST['email']??'')));$currency=module_currency((string)($_POST['currency']??'RWF'));if(mb_strlen($name)<2||mb_strlen($name)>200||!filter_var($email,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Valid advertiser details are required.');db()->prepare('INSERT INTO advertisers(name,contact_email,billing_currency,created_by) VALUES (?,?,?,?)')->execute([$name,$email,$currency,(int)$me['id']]);$id=(int)db()->lastInsertId();audit_log('advertiser_created','advertiser',$id,$currency);flash('Advertiser created and audited.');module_redirect('advertising');}
  elseif($act==='create_campaign'){require_permission('advertising.manage');$adv=(int)($_POST['advertiser_id']??0);$advertiser=query_one("SELECT id FROM advertisers WHERE id=? AND status NOT IN ('suspended','closed')",[$adv]);$name=trim((string)($_POST['name']??''));$model=(string)($_POST['pricing_model']??'FIXED');$budget=max(0,(int)($_POST['budget_minor']??0));$currency=module_currency((string)($_POST['currency']??'RWF'));$starts=module_date((string)($_POST['starts_at']??''),'Campaign start');$ends=module_date((string)($_POST['ends_at']??''),'Campaign end');if(!$advertiser||mb_strlen($name)<3||!in_array($model,['CPM','CPC','FIXED'],true)||$budget<1||strtotime($ends)<=strtotime($starts))throw new RuntimeException('Valid advertiser, campaign, budget and date range are required.');db()->prepare("INSERT INTO ad_campaigns(advertiser_id,name,pricing_model,budget_minor,currency,starts_at,ends_at,status,created_by) VALUES (?,?,?,?,?,?,?,'draft',?)")->execute([$adv,$name,$model,$budget,$currency,$starts,$ends,(int)$me['id']]);$id=(int)db()->lastInsertId();audit_log('campaign_created','ad_campaign',$id,$model);flash('Campaign draft created. Submit it for independent approval after evidence review.');module_redirect('advertising');}
  elseif($act==='submit_campaign'){require_permission('advertising.manage');$id=(int)($_POST['id']??0);$s=db()->prepare("UPDATE ad_campaigns SET status='pending_approval' WHERE id=? AND status='draft'");$s->execute([$id]);if($s->rowCount()!==1)throw new RuntimeException('Only a draft campaign can be submitted.');audit_log('campaign_submitted','ad_campaign',$id);flash('Campaign submitted to an independent approver.');module_redirect('advertising');}
  elseif($act==='approve_campaign'){require_permission('advertising.approve');$id=(int)($_POST['id']??0);$campaign=query_one('SELECT * FROM ad_campaigns WHERE id=?',[$id]);if(!$campaign||$campaign['status']!=='pending_approval')throw new RuntimeException('Campaign is not awaiting approval.');if((int)$campaign['created_by']===(int)$me['id'])throw new RuntimeException('The campaign creator cannot approve the same campaign.');$s=db()->prepare("UPDATE ad_campaigns SET status='approved',approved_by=? WHERE id=? AND status='pending_approval'");$s->execute([(int)$me['id'],$id]);if($s->rowCount()!==1)throw new RuntimeException('Campaign changed concurrently.');audit_log('campaign_approved','ad_campaign',$id);flash('Campaign approved. Activation still requires valid dates and creative/disclosure evidence.');module_redirect('advertising');}
  elseif($act==='campaign_status'){require_permission('advertising.manage');$id=(int)($_POST['id']??0);$to=(string)($_POST['status']??'');$campaign=query_one('SELECT * FROM ad_campaigns WHERE id=?',[$id]);if(!$campaign)throw new RuntimeException('Campaign missing.');$from=(string)$campaign['status'];$allowed=['approved'=>['active','cancelled'],'active'=>['paused','completed','cancelled'],'paused'=>['active','completed','cancelled']];if(!in_array($to,$allowed[$from]??[],true))throw new RuntimeException('Invalid campaign transition.');if($to==='active'&&(time()<strtotime($campaign['starts_at'])||time()>=strtotime($campaign['ends_at'])))throw new RuntimeException('Campaign can activate only inside its approved date range.');$s=db()->prepare('UPDATE ad_campaigns SET status=? WHERE id=? AND status=?');$s->execute([$to,$id,$from]);if($s->rowCount()!==1)throw new RuntimeException('Campaign changed concurrently.');audit_log('campaign_status','ad_campaign',$id,$from.'>'.$to);flash('Campaign status updated.');module_redirect('advertising');}
  elseif($act==='create_invoice'){require_permission('finance.invoice.create');$adv=(int)($_POST['advertiser_id']??0);$campaignId=(int)($_POST['campaign_id']??0);$amount=max(0,(int)($_POST['amount_minor']??0));$number=trim((string)($_POST['invoice_number']??''));$key=trim((string)($_POST['idempotency_key']??''));$currency=module_currency((string)($_POST['currency']??'RWF'));$advertiser=query_one('SELECT id FROM advertisers WHERE id=?',[$adv]);$campaign=$campaignId?query_one('SELECT * FROM ad_campaigns WHERE id=? AND advertiser_id=?',[$campaignId,$adv]):null;if(!$advertiser||($campaignId&&!$campaign)||$amount<1||$number===''||mb_strlen($key)<12)throw new RuntimeException('Invoice number, positive amount, valid advertiser/campaign and a 12+ character idempotency key are required.');if($campaign&&$campaign['currency']!==$currency)throw new RuntimeException('Invoice and campaign currencies must match.');$due=trim((string)($_POST['due_at']??''));$due=$due!==''?module_date($due,'Invoice due',true):null;db()->prepare('INSERT INTO invoices(advertiser_id,campaign_id,invoice_number,idempotency_key,amount_minor,currency,status,due_at,issued_at,created_by) VALUES (?,?,?,?,?,?,\'issued\',?,'.sql_now().',?)')->execute([$adv,$campaignId?:null,$number,$key,$amount,$currency,$due,(int)$me['id']]);$id=(int)db()->lastInsertId();audit_log('invoice_issued','invoice',$id,$number);flash('Invoice issued. A different authorized user must record payment.');module_redirect('finance');}
  elseif($act==='record_payment'){require_permission('finance.payment.record');$invoiceId=(int)($_POST['invoice_id']??0);$invoice=query_one("SELECT i.*,COALESCE((SELECT SUM(p.amount_minor) FROM payments p WHERE p.invoice_id=i.id),0) paid_minor FROM invoices i WHERE i.id=?",[$invoiceId]);if(!$invoice||!in_array($invoice['status'],['issued','partially_paid','overdue'],true))throw new RuntimeException('Invoice cannot receive payment.');if((int)$invoice['created_by']===(int)$me['id'])throw new RuntimeException('Separation of duties: the invoice creator cannot record its payment.');$amount=max(0,(int)($_POST['amount_minor']??0));$outstanding=(int)$invoice['amount_minor']-(int)$invoice['paid_minor'];$currency=module_currency((string)($_POST['currency']??''));$method=trim((string)($_POST['method']??''));$reference=substr(trim((string)($_POST['reference']??'')),0,160)?:null;$key=trim((string)($_POST['idempotency_key']??''));if($amount<1||$amount>$outstanding||$currency!==$invoice['currency']||mb_strlen($method)<2||mb_strlen($key)<12)throw new RuntimeException('Payment must match currency and balance, with method and a 12+ character idempotency key.');$received=module_date((string)($_POST['received_at']??''),'Payment receipt');db()->beginTransaction();try{db()->prepare('INSERT INTO payments(invoice_id,idempotency_key,amount_minor,currency,method,reference,received_at,recorded_by) VALUES (?,?,?,?,?,?,?,?)')->execute([$invoiceId,$key,$amount,$currency,$method,$reference,$received,(int)$me['id']]);$status=(int)$invoice['paid_minor']+$amount>=(int)$invoice['amount_minor']?'paid':'partially_paid';db()->prepare('UPDATE invoices SET status=? WHERE id=?')->execute([$status,$invoiceId]);db()->commit();}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();throw $e;}audit_log('payment_recorded','invoice',$invoiceId,module_money($amount,$currency));flash('Payment recorded. External statement reconciliation remains a separate control.');module_redirect('finance');}
  elseif($act==='save_setting'){require_permission('system.configure');$key=preg_replace('/[^a-z0-9_.-]/','',strtolower((string)$_POST['key']));if($key===''||str_starts_with($key,'secret.'))throw new RuntimeException('Invalid or secret setting key.');$value=substr((string)$_POST['value'],0,5000);if(db_is_sqlite())db()->prepare('INSERT INTO system_settings(setting_key,setting_value,is_secret,updated_by,updated_at) VALUES (?,?,0,?,datetime(\'now\')) ON CONFLICT(setting_key) DO UPDATE SET setting_value=excluded.setting_value,updated_by=excluded.updated_by,updated_at=datetime(\'now\')')->execute([$key,$value,(int)$me['id']]);else db()->prepare('INSERT INTO system_settings(setting_key,setting_value,is_secret,updated_by) VALUES (?,?,0,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value),updated_by=VALUES(updated_by)')->execute([$key,$value,(int)$me['id']]);audit_log('update','system_setting',0,$key);}
  else throw new RuntimeException('Unknown module action.');flash('Setting saved and audited.');module_redirect($module);
 }catch(Throwable $e){error_log('Management module action failed: '.$e->getMessage());$error=$e instanceof PDOException?'Operation could not be completed. Check unique identifiers and retry.':$e->getMessage();}
}
