<?php elseif($module==='advertising'):module_require_any(['advertising.manage','advertising.approve']);$ads=query_all('SELECT * FROM advertisers ORDER BY created_at DESC');$campaigns=query_all('SELECT c.*,a.name advertiser,creator.full_name creator_name,approver.full_name approver_name FROM ad_campaigns c JOIN advertisers a ON a.id=c.advertiser_id JOIN users creator ON creator.id=c.created_by LEFT JOIN users approver ON approver.id=c.approved_by ORDER BY c.created_at DESC');?><section class="setting-panel"><h2>Campaign workflow</h2><p>Draft → pending approval → approved → active. Commercial approval never grants editorial authority. Contract, creative-rights and disclosure evidence remain required.</p><?php foreach($campaigns as $c):?><article class="inbox-card"><h3><?=e($c['name'])?></h3><p><?=e($c['advertiser'])?> · <?=e($c['pricing_model'])?> · <?=e(module_money((int)$c['budget_minor'],$c['currency']))?> · <b><?=e($c['status'])?></b></p><small>Created by <?=e($c['creator_name'])?><?php if($c['approver_name']):?> · Approved by <?=e($c['approver_name'])?><?php endif;?> · <?=e(display_date($c['starts_at']))?> → <?=e(display_date($c['ends_at']))?></small><div class="ops-actions"><?php if(can('advertising.manage')&&$c['status']==='draft'):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="submit_campaign"><input type="hidden" name="id" value="<?=$c['id']?>"><button>SUBMIT FOR APPROVAL</button></form><?php endif;?><?php if(can('advertising.approve')&&$c['status']==='pending_approval'&&(int)$c['created_by']!==(int)$me['id']):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="approve_campaign"><input type="hidden" name="id" value="<?=$c['id']?>"><button>APPROVE</button></form><?php endif;?><?php if(can('advertising.manage')&&in_array($c['status'],['approved','active','paused'],true)):?><?php foreach($c['status']==='approved'?['active','cancelled']:($c['status']==='active'?['paused','completed','cancelled']:['active','completed','cancelled']) as $to):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="campaign_status"><input type="hidden" name="id" value="<?=$c['id']?>"><input type="hidden" name="status" value="<?=e($to)?>"><button><?=e(strtoupper($to))?></button></form><?php endforeach;?><?php endif;?></div></article><?php endforeach;?></section><?php if(can('advertising.manage')):?><div class="workflow-grid"><section class="setting-panel"><h2>Add advertiser</h2><form method="post" class="public-form"><?=csrf_field()?><input type="hidden" name="action" value="create_advertiser"><label>NAME<input name="name" maxlength="200" required></label><label>EMAIL<input type="email" name="email" required></label><label>CURRENCY<input name="currency" value="RWF" maxlength="3" pattern="[A-Za-z]{3}"></label><button>ADD ADVERTISER</button></form></section><section class="setting-panel"><h2>Create campaign</h2><form method="post" class="public-form"><?=csrf_field()?><input type="hidden" name="action" value="create_campaign"><label>ADVERTISER<select name="advertiser_id"><?php foreach($ads as $a):?><option value="<?=$a['id']?>"><?=e($a['name'])?></option><?php endforeach;?></select></label><label>NAME<input name="name" minlength="3" maxlength="200" required></label><label>PRICING<select name="pricing_model"><option>FIXED</option><option>CPM</option><option>CPC</option></select></label><label>BUDGET IN SMALLEST CURRENCY UNIT<input type="number" min="1" name="budget_minor" required></label><small>For RWF, enter whole francs.</small><label>CURRENCY<input name="currency" value="RWF" maxlength="3" pattern="[A-Za-z]{3}"></label><label>START<input type="datetime-local" name="starts_at" required></label><label>END<input type="datetime-local" name="ends_at" required></label><button>CREATE DRAFT</button></form></section></div><?php endif;?>
<?php elseif($module==='finance'):require_permission('finance.view');$invoices=query_all('SELECT i.*,a.name advertiser,c.name campaign,creator.full_name creator_name,COALESCE((SELECT SUM(p.amount_minor) FROM payments p WHERE p.invoice_id=i.id),0) paid_minor FROM invoices i JOIN advertisers a ON a.id=i.advertiser_id LEFT JOIN ad_campaigns c ON c.id=i.campaign_id JOIN users creator ON creator.id=i.created_by ORDER BY i.created_at DESC');?><section class="setting-panel"><h2>Invoices and payments</h2><p>Invoice creation and payment recording are separated by user identity. External bank/mobile-money statement reconciliation is still a production gate.</p><?php foreach($invoices as $i):$outstanding=max(0,(int)$i['amount_minor']-(int)$i['paid_minor']);?><article class="inbox-card"><h3><?=e($i['invoice_number'])?> · <?=e($i['advertiser'])?></h3><p><?=e(module_money((int)$i['amount_minor'],$i['currency']))?> total · <?=e(module_money((int)$i['paid_minor'],$i['currency']))?> paid · <?=e(module_money($outstanding,$i['currency']))?> outstanding · <b><?=e($i['status'])?></b></p><small>Created by <?=e($i['creator_name'])?><?php if($i['campaign']):?> · Campaign <?=e($i['campaign'])?><?php endif;?></small><?php if(can('finance.payment.record')&&$outstanding>0&&(int)$i['created_by']!==(int)$me['id']&&!in_array($i['status'],['void','paid'],true)):?><form method="post" class="public-form"><?=csrf_field()?><input type="hidden" name="action" value="record_payment"><input type="hidden" name="invoice_id" value="<?=$i['id']?>"><label>AMOUNT<input type="number" name="amount_minor" min="1" max="<?=$outstanding?>" required></label><label>CURRENCY<input name="currency" value="<?=e($i['currency'])?>" readonly></label><label>METHOD<input name="method" maxlength="60" required></label><label>REFERENCE<input name="reference" maxlength="160"></label><label>RECEIVED AT<input type="datetime-local" name="received_at" required></label><label>IDEMPOTENCY KEY<input name="idempotency_key" minlength="12" maxlength="120" required></label><button>RECORD PAYMENT</button></form><?php endif;?></article><?php endforeach;?></section><?php if(can('finance.invoice.create')):$ads=query_all('SELECT id,name FROM advertisers ORDER BY name');$campaignOptions=query_all("SELECT id,name FROM ad_campaigns WHERE status IN ('approved','active','completed') ORDER BY name");?><section class="setting-panel"><h2>Issue invoice</h2><form method="post" class="public-form"><?=csrf_field()?><input type="hidden" name="action" value="create_invoice"><label>ADVERTISER<select name="advertiser_id"><?php foreach($ads as $a):?><option value="<?=$a['id']?>"><?=e($a['name'])?></option><?php endforeach;?></select></label><label>CAMPAIGN (OPTIONAL)<select name="campaign_id"><option value="0">No campaign link</option><?php foreach($campaignOptions as $c):?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach;?></select></label><label>INVOICE NUMBER<input name="invoice_number" maxlength="80" required></label><label>IDEMPOTENCY KEY<input name="idempotency_key" minlength="12" maxlength="120" required></label><label>AMOUNT IN SMALLEST CURRENCY UNIT<input type="number" min="1" name="amount_minor" required></label><small>RWF uses whole francs; two-decimal currencies use cents.</small><label>CURRENCY<input name="currency" value="RWF" maxlength="3" pattern="[A-Za-z]{3}"></label><label>DUE<input type="datetime-local" name="due_at"></label><button>ISSUE INVOICE</button></form></section><?php endif;?>
<?php elseif($module==='analytics'):module_require_any(['analytics.view','analytics.system','analytics.commercial']);$events=query_all('SELECT event_type,COUNT(*) n FROM analytics_events GROUP BY event_type');?><section class="setting-panel"><h2>First-party analytics</h2><p>No IP address or cross-site identifier is stored. Counts are operational signals, not certified audience measurement.</p><?php foreach($events as $v):?><p><?=e($v['event_type'])?>: <b><?=(int)$v['n']?></b></p><?php endforeach;?></section>
<?php elseif($module==='system'): require_permission('system.configure');?><section class="setting-panel"><h2>System administration</h2><p><a href="<?=e(path('admin/roles.php'))?>">Open staff role & permission matrix →</a></p><p>Non-secret settings only. Every change is audited.</p><form method="post" class="public-form"><?=csrf_field()?><input type="hidden" name="action" value="save_setting"><label>SETTING KEY<input name="key" pattern="[a-zA-Z0-9_.-]+" required></label><label>VALUE<textarea name="value" required></textarea></label><button>SAVE SETTING</button></form></section>
<?php else:?><p>Module not found.</p><?php endif;?></main></body></html>
